-- Phase 1 cleanup BEFORE snapshot (attributes). Geometries referenced by md5/npoints only.
-- Generated from disposable DB mirror of production admin tables before migration apply.
BEGIN;
CREATE TABLE IF NOT EXISTS _phase1_cleanup_snapshot_areas (
  id bigint PRIMARY KEY, public_id uuid, parent_id bigint, admin_level_code text, admin_area_type_code text,
  canonical_name text, slug text, is_active boolean, verification_status text,
  is_official_boundary boolean, address_usage text, is_public_usable boolean,
  geom_md5 text, geom_npoints int
);
TRUNCATE _phase1_cleanup_snapshot_areas;
CREATE TABLE IF NOT EXISTS _phase1_cleanup_snapshot_names (LIKE core.core_admin_area_names INCLUDING DEFAULTS);
TRUNCATE _phase1_cleanup_snapshot_names;
COMMIT;